// Replaces the MainActivity generated by `flet build apk`.
// Turns "Share > LinkVault" (ACTION_SEND text/plain) into the deep link
// linkvault://app/save?text=<shared text>, which Flet hands to Python as a route.
package __PACKAGE__

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import io.flutter.embedding.android.FlutterActivity

class MainActivity : FlutterActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        rewriteShareIntent(intent)
        super.onCreate(savedInstanceState)
    }

    override fun onNewIntent(intent: Intent) {
        rewriteShareIntent(intent)
        super.onNewIntent(intent)
    }

    private fun rewriteShareIntent(intent: Intent?) {
        if (intent?.action != Intent.ACTION_SEND) return
        val text = intent.getStringExtra(Intent.EXTRA_TEXT) ?: return
        intent.action = Intent.ACTION_VIEW
        intent.data = Uri.parse("linkvault://app/save?text=" + Uri.encode(text))
    }
}
